import type { CalendarType, FirstDayOfWeek } from './types';

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface DateLimits {
  minDate: Date | null;
  maxDate: Date | null;
  disabledDates: Set<string>;
  disabledDateFn: ((d: Date) => boolean) | null;
}

export interface CalendarComponents {
  year: number;
  month: number; // 0-indexed
  day: number;
}

export interface CalendarDay {
  date: Date; // always a Gregorian JS Date
  components: CalendarComponents; // year/month/day in the target calendar
  day: number;
  month: number; // 0-indexed in target calendar
  year: number;
  isCurrentMonth: boolean;
  isToday: boolean;
  isSelected: boolean;
  isDisabled: boolean;
  isInRange: boolean;
  isRangeStart: boolean;
  isRangeEnd: boolean;
}

export interface CalendarWeek {
  days: CalendarDay[];
}

export interface CalendarMonth {
  year: number;
  month: number; // 0-indexed
  calendar: CalendarType;
  weeks: CalendarWeek[];
  firstDayOfMonth: CalendarDay;
}

// ---------------------------------------------------------------------------
// Intl helpers
// ---------------------------------------------------------------------------

/**
 * Build a cached Intl.DateTimeFormat for calendar arithmetic.
 */
const _fmtCache = new Map<string, Intl.DateTimeFormat>();

function getIntlFmt(calendar: CalendarType, locale?: string): Intl.DateTimeFormat {
  const calMap: Record<CalendarType, string> = {
    gregorian: 'gregory',
    jalali: 'persian',
    hijri: 'islamic-umalqura',
  };
  const cal = calMap[calendar];
  const loc = locale || (calendar === 'jalali' ? 'fa-IR' : calendar === 'hijri' ? 'ar-SA' : 'en-US');
  const key = `${cal}__${loc}`;
  if (!_fmtCache.has(key)) {
    _fmtCache.set(
      key,
      new Intl.DateTimeFormat(`${loc}-u-ca-${cal}`, {
        year: 'numeric',
        month: 'numeric',
        day: 'numeric',
      })
    );
  }
  return _fmtCache.get(key)!;
}

/**
 * Extract calendar year/month/day for a given Gregorian Date.
 * Returns null when Intl is unavailable for the calendar.
 */
/** Convert Persian/Arabic-Indic digits to ASCII digits for parseInt. */
function normalizeDigits(str: string): string {
  return str
    .replace(/[۰-۹]/g, (c) => String(c.charCodeAt(0) - 0x06f0))
    .replace(/[٠-٩]/g, (c) => String(c.charCodeAt(0) - 0x0660));
}

export function toCalendarComponents(date: Date, calendar: CalendarType): CalendarComponents | null {
  try {
    const fmt = getIntlFmt(calendar);
    const parts = fmt.formatToParts(date);
    const get = (type: string) => {
      const raw = parts.find((p) => p.type === type)?.value ?? '0';
      return parseInt(normalizeDigits(raw), 10);
    };
    // Intl month is 1-indexed → convert to 0-indexed
    return { year: get('year'), month: get('month') - 1, day: get('day') };
  } catch {
    // Fallback: gregorian
    return { year: date.getFullYear(), month: date.getMonth(), day: date.getDate() };
  }
}

// ---------------------------------------------------------------------------
// Date comparison & formatting
// ---------------------------------------------------------------------------

/** Return YYYY-MM-DD ISO string from a JS Date (Gregorian). */
export function ISOFromDate(date: Date): string {
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, '0');
  const d = String(date.getDate()).padStart(2, '0');
  return `${y}-${m}-${d}`;
}

/** Check if two JS Dates represent the same calendar day. */
export function dateEquals(a: Date | null, b: Date | null): boolean {
  if (!a || !b) return false;
  return (
    a.getFullYear() === b.getFullYear() &&
    a.getMonth() === b.getMonth() &&
    a.getDate() === b.getDate()
  );
}

/** Alias kept for backward compatibility with older code in DatePicker.ts. */
export function isSameDay(a: Date, b: Date): boolean {
  return dateEquals(a, b);
}

/** Check if a date is today. */
export function isToday(date: Date): boolean {
  return dateEquals(date, new Date());
}

/** Format a JS Date with a simple pattern (YYYY-MM-DD, DD/MM/YYYY, etc.). */
export function formatDate(date: Date, format: string): string {
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, '0');
  const d = String(date.getDate()).padStart(2, '0');
  return format.replace('YYYY', String(y)).replace('MM', m).replace('DD', d);
}

// ---------------------------------------------------------------------------
// Calendar-aware days-in-month
// ---------------------------------------------------------------------------

/**
 * Return the number of days in a given month for the target calendar.
 * year & month are in the target calendar's coordinate system (month 0-indexed).
 */
export function getDaysInMonth(year: number, month: number, calendar: CalendarType = 'gregorian'): number {
  if (calendar === 'gregorian') {
    return new Date(year, month + 1, 0).getDate();
  }

  // For Jalali / Hijri, probe Intl by finding the Gregorian Date that
  // corresponds to day 1 of month+1 in the target calendar, then
  // subtract one day.
  try {
    // Walk from a rough Gregorian estimate
    const roughGregorian = calendarToGregorian(year, month + 1, 1, calendar);
    if (roughGregorian) {
      // The last day of this month = day before the first of next month
      const next = calendarToGregorian(year, month + 1, 1, calendar);
      if (next) {
        // subtract 1 ms from next month day-1
        const lastDay = new Date(next.getTime() - 1);
        const comp = toCalendarComponents(lastDay, calendar);
        if (comp && comp.year === year && comp.month === month) {
          return comp.day;
        }
      }
    }
  } catch {
    // ignore
  }

  // Jalali rule fallback (without Intl)
  if (calendar === 'jalali') {
    if (month <= 5) return 31;
    if (month <= 10) return 30;
    // Month 11 (Esfand): 29 in normal year, 30 in leap
    return isJalaliLeapYear(year) ? 30 : 29;
  }

  // Hijri: alternate 30/29 days
  return month % 2 === 0 ? 30 : 29;
}

function isJalaliLeapYear(year: number): boolean {
  const leapRemainders = [1, 5, 9, 13, 17, 22, 26, 30];
  return leapRemainders.includes(((year - 474) % 2820) % 33);
}

// ---------------------------------------------------------------------------
// Calendar ↔ Gregorian conversion
// ---------------------------------------------------------------------------

/**
 * Convert calendar-specific year/month/day to a JS Date.
 * month is 0-indexed.
 */
export function calendarToGregorian(
  year: number,
  month: number, // 0-indexed
  day: number,
  calendar: CalendarType
): Date | null {
  if (calendar === 'gregorian') {
    return new Date(year, month, day);
  }

  // Use Intl to do the reverse mapping by binary-searching nearby dates
  try {
    return intlReverseDate(year, month, day, calendar);
  } catch {
    return null;
  }
}

/**
 * Binary-search approach: find the Gregorian Date whose Intl representation
 * matches the requested calendar year/month/day.
 */
function intlReverseDate(
  targetYear: number,
  targetMonth: number, // 0-indexed
  targetDay: number,
  calendar: CalendarType
): Date | null {
  // Rough Gregorian estimate
  // Jalali year + 621 ≈ Gregorian year (e.g. 1405 + 621 = 2026)
  // Hijri year + 579 ≈ Gregorian year (approximate, lunar calendar shifts)
  let roughYear: number;
  if (calendar === 'jalali') {
    roughYear = targetYear + 621;
  } else {
    // Hijri is lunar — multiply by ~0.9702 for better approximation
    roughYear = Math.round(targetYear * 0.9702 + 621.57);
  }
  const rough = new Date(roughYear, targetMonth, targetDay);

  const toComp = (d: Date) => toCalendarComponents(d, calendar);

  // Search within ±400 days to handle edge cases and calendar drift
  for (let offset = 0; offset <= 400; offset++) {
    for (const sign of offset === 0 ? [0] : [1, -1]) {
      const candidate = new Date(rough.getTime() + sign * offset * 86400000);
      const comp = toComp(candidate);
      if (
        comp &&
        comp.year === targetYear &&
        comp.month === targetMonth &&
        comp.day === targetDay
      ) {
        return candidate;
      }
    }
  }
  return null;
}

// ---------------------------------------------------------------------------
// Parsing
// ---------------------------------------------------------------------------

/**
 * Parse a date string to a JS Date.
 * Supports:
 *   - ISO gregorian: "2026-10-06"
 *   - Jalali ISO:    "1405-07-14"  (when calendar = 'jalali')
 *   - Hijri ISO:     "1448-03-12"  (when calendar = 'hijri')
 * Returns null for invalid input.
 */
export function parseDateValue(
  value: string,
  calendar: CalendarType = 'gregorian'
): Date | null {
  if (typeof value !== 'string') return null;
  const match = value.match(/^(\d{1,4})-(\d{1,2})-(\d{1,2})$/);
  if (!match) return null;

  const year = parseInt(match[1], 10);
  const month = parseInt(match[2], 10) - 1; // 0-indexed
  const day = parseInt(match[3], 10);

  if (month < 0 || month > 11 || day < 1 || day > 31) return null;

  if (calendar === 'gregorian') {
    const d = new Date(year, month, day);
    // Validate: JS Date will roll over invalid dates
    if (d.getFullYear() !== year || d.getMonth() !== month || d.getDate() !== day) {
      return null;
    }
    return d;
  }

  return calendarToGregorian(year, month, day, calendar);
}

/** Legacy wrapper used in DatePicker.ts */
export function parseDate(value: string | string[]): Date[] {
  if (Array.isArray(value)) {
    return value
      .map((v) => parseDateValue(v, 'gregorian'))
      .filter((d): d is Date => d !== null);
  }
  const result = parseDateValue(value, 'gregorian');
  return result ? [result] : [];
}

// ---------------------------------------------------------------------------
// Disabled check
// ---------------------------------------------------------------------------

export function isDateDisabled(date: Date, limits: DateLimits): boolean {
  if (limits.minDate) {
    const min = new Date(
      limits.minDate.getFullYear(),
      limits.minDate.getMonth(),
      limits.minDate.getDate()
    );
    if (date < min) return true;
  }
  if (limits.maxDate) {
    const max = new Date(
      limits.maxDate.getFullYear(),
      limits.maxDate.getMonth(),
      limits.maxDate.getDate() + 1
    );
    if (date >= max) return true;
  }
  if (limits.disabledDates.has(ISOFromDate(date))) return true;
  if (limits.disabledDateFn && limits.disabledDateFn(date)) return true;
  return false;
}

/** Legacy signature used in older code. */
export function isDisabledDate(
  date: Date,
  minDate: Date | null,
  maxDate: Date | null,
  disabledDates: Set<string>,
  disabledDateFn: ((d: Date) => boolean) | null
): boolean {
  return isDateDisabled(date, { minDate, maxDate, disabledDates, disabledDateFn });
}

// ---------------------------------------------------------------------------
// Week-day names
// ---------------------------------------------------------------------------

export function getWeekdayNames(localeCode: string, firstDay: FirstDayOfWeek): string[] {
  // Lazy import to avoid circular dep at module level
  // eslint-disable-next-line @typescript-eslint/no-var-requires
  const { getLocale } = require('./i18n') as typeof import('./i18n');
  const locale = getLocale(localeCode);
  const days = [...locale.weekDay];
  // Rotate so that firstDay comes first
  for (let i = 0; i < firstDay; i++) {
    const d = days.shift();
    if (d !== undefined) days.push(d);
  }
  return days;
}

// ---------------------------------------------------------------------------
// Build full calendar month
// ---------------------------------------------------------------------------

/**
 * Build a CalendarMonth with week rows.
 * All dates are stored as Gregorian JS Dates internally.
 */
export function buildCalendarMonth(
  year: number,          // in target calendar
  month: number,         // 0-indexed, in target calendar
  firstDayOfWeek: number, // 0=Sun,1=Mon,6=Sat
  calendar: CalendarType,
  limits: DateLimits,
  selectedDates: Date[] = [],
  rangeStart?: Date | null,
  rangeEnd?: Date | null
): CalendarMonth {
  const today = new Date();

  // Find the Gregorian date of day-1 of this calendar month
  const firstGregorian = calendarToGregorian(year, month, 1, calendar);
  if (!firstGregorian) {
    return { year, month, calendar, weeks: [], firstDayOfMonth: {} as CalendarDay };
  }

  // How many days in this month?
  const daysInThisMonth = computeDaysInMonth(year, month, calendar);

  // Build a flat list of CalendarDay objects covering full weeks
  const days: CalendarDay[] = [];

  // Day-of-week for the first of the month (0=Sun … 6=Sat)
  const firstDow = firstGregorian.getDay();
  // How many leading days from previous month?
  const leadingDays = ((firstDow - firstDayOfWeek) + 7) % 7;

  // Leading days (from prev month)
  for (let i = leadingDays; i > 0; i--) {
    const gDate = new Date(firstGregorian.getTime() - i * 86400000);
    days.push(makeCalendarDay(gDate, calendar, false, today, limits, selectedDates, rangeStart, rangeEnd));
  }

  // Current month days
  for (let d = 0; d < daysInThisMonth; d++) {
    const gDate = new Date(firstGregorian.getTime() + d * 86400000);
    days.push(makeCalendarDay(gDate, calendar, true, today, limits, selectedDates, rangeStart, rangeEnd));
  }

  // Trailing days (fill to complete last week)
  const total = Math.ceil(days.length / 7) * 7;
  const trailing = total - days.length;
  const lastGregorian = new Date(firstGregorian.getTime() + (daysInThisMonth - 1) * 86400000);
  for (let i = 1; i <= trailing; i++) {
    const gDate = new Date(lastGregorian.getTime() + i * 86400000);
    days.push(makeCalendarDay(gDate, calendar, false, today, limits, selectedDates, rangeStart, rangeEnd));
  }

  // Chunk into weeks
  const weeks: CalendarWeek[] = [];
  for (let i = 0; i < days.length; i += 7) {
    weeks.push({ days: days.slice(i, i + 7) });
  }

  const firstDayOfMonth = days.find((d) => d.isCurrentMonth && d.components.day === 1) ?? days[0];

  return { year, month, calendar, weeks, firstDayOfMonth };
}

// ---------------------------------------------------------------------------
// Legacy flat array builder (used by DatePicker.ts renderCalendar)
// ---------------------------------------------------------------------------

export function generateMonthDays(
  year: number,
  month: number,
  selectedDates: Date[],
  minDate: Date | null,
  maxDate: Date | null,
  disabledDates: Set<string>,
  disabledDateFn: ((d: Date) => boolean) | null,
  localeCode: string,
  calendar: CalendarType,
  firstDayOfWeek?: number
): CalendarDay[] {
  // Get firstDayOfWeek from locale if not provided
  let fdow = firstDayOfWeek;
  if (fdow === undefined) {
    try {
      const { getLocale } = require('./i18n') as typeof import('./i18n');
      fdow = getLocale(localeCode).firstDay;
    } catch {
      fdow = 0;
    }
  }

  const limits: DateLimits = { minDate, maxDate, disabledDates, disabledDateFn };

  // For gregorian, year/month are Gregorian. For other calendars, we need
  // to convert: the caller currently passes Gregorian viewYear/viewMonth
  // (since state stores Gregorian). We pass them as-is for gregorian.
  // For jalali/hijri, the state viewYear/viewMonth should be in that calendar's
  // coordinate system. See DatePicker.ts for how it stores viewDate.
  const month_ = buildCalendarMonth(year, month, fdow ?? 0, calendar, limits, selectedDates);
  // Flatten weeks back to days
  return month_.weeks.flatMap((w) => w.days);
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function computeDaysInMonth(year: number, month: number, calendar: CalendarType): number {
  if (calendar === 'gregorian') {
    return new Date(year, month + 1, 0).getDate();
  }
  // Find first day of next month and subtract
  const nextMonth = month === 11 ? 0 : month + 1;
  const nextYear = month === 11 ? year + 1 : year;
  const firstOfNext = calendarToGregorian(nextYear, nextMonth, 1, calendar);
  const firstOfThis = calendarToGregorian(year, month, 1, calendar);
  if (firstOfNext && firstOfThis) {
    return Math.round((firstOfNext.getTime() - firstOfThis.getTime()) / 86400000);
  }
  return getDaysInMonth(year, month, calendar);
}

function isInDateRange(date: Date, rangeStart?: Date | null, rangeEnd?: Date | null): boolean {
  if (!rangeStart || !rangeEnd) return false;
  const t = date.getTime();
  const s = Math.min(rangeStart.getTime(), rangeEnd.getTime());
  const e = Math.max(rangeStart.getTime(), rangeEnd.getTime());
  return t > s && t < e;
}

function makeCalendarDay(
  gDate: Date,
  calendar: CalendarType,
  isCurrentMonth: boolean,
  today: Date,
  limits: DateLimits,
  selectedDates: Date[],
  rangeStart?: Date | null,
  rangeEnd?: Date | null
): CalendarDay {
  const components = toCalendarComponents(gDate, calendar) ?? {
    year: gDate.getFullYear(),
    month: gDate.getMonth(),
    day: gDate.getDate(),
  };

  const selected = selectedDates.some((d) => dateEquals(d, gDate));
  const rStart = rangeStart ? dateEquals(gDate, rangeStart) : false;
  const rEnd = rangeEnd ? dateEquals(gDate, rangeEnd) : false;
  const inRange = isInDateRange(gDate, rangeStart, rangeEnd);

  return {
    date: gDate,
    components,
    day: components.day,
    month: components.month,
    year: components.year,
    isCurrentMonth,
    isToday: dateEquals(gDate, today),
    isSelected: selected || rStart || rEnd,
    isDisabled: isDateDisabled(gDate, limits),
    isInRange: inRange,
    isRangeStart: rStart,
    isRangeEnd: rEnd,
  };
}