import type { LocaleConfig } from './types';

// ---------------------------------------------------------------------------
// Cell element
// ---------------------------------------------------------------------------

export function createCalendarCellElement(
  cell: {
    date: Date;
    day: number;
    month: number;
    year: number;
    isCurrentMonth: boolean;
    isToday: boolean;
    isSelected: boolean;
    isDisabled: boolean;
    isInRange: boolean;
    isRangeStart: boolean;
    isRangeEnd: boolean;
  },
  locale: LocaleConfig,
  displayLabel?: string
): HTMLElement {
  const el = document.createElement('button');
  el.type = 'button';
  el.className = 'dp-day';

  if (cell.isSelected || cell.isRangeStart || cell.isRangeEnd) {
    el.classList.add('dp-day--selected');
  }
  if (cell.isToday && !cell.isSelected) {
    el.classList.add('dp-day--today');
  }
  if (cell.isDisabled) {
    el.classList.add('dp-day--disabled');
    el.setAttribute('aria-disabled', 'true');
    el.tabIndex = -1;
  } else {
    el.tabIndex = -1;
  }
  if (cell.isRangeStart) el.classList.add('dp-day--range-start');
  if (cell.isRangeEnd) el.classList.add('dp-day--range-end');
  if (cell.isInRange) el.classList.add('dp-day--in-range');
  if (!cell.isCurrentMonth) el.classList.add('dp-day--other-month');

  // ARIA
  el.setAttribute('role', 'gridcell');
  el.setAttribute('aria-selected', cell.isSelected || cell.isRangeStart || cell.isRangeEnd ? 'true' : 'false');
  el.setAttribute('data-date', cell.date.toISOString().slice(0, 10));

  // Display label: use provided label or localize number if RTL
  const label = displayLabel ?? localizeDigits(String(cell.day), locale.code);
  el.textContent = label;

  // Accessible label for screen readers
  const ariaLabel = buildDayAriaLabel(cell.date, locale);
  el.setAttribute('aria-label', ariaLabel);

  return el;
}

function localizeDigits(str: string, localeCode: string): string {
  if (localeCode.startsWith('fa') || localeCode.startsWith('ar')) {
    return str.replace(/\d/g, (d) => '٠١٢٣٤٥٦٧٨٩'[parseInt(d)]);
  }
  return str;
}

function buildDayAriaLabel(date: Date, locale: LocaleConfig): string {
  try {
    return date.toLocaleDateString(locale.code, {
      year: 'numeric',
      month: 'long',
      day: 'numeric',
    });
  } catch {
    return date.toDateString();
  }
}

// ---------------------------------------------------------------------------
// Weekday header row
// ---------------------------------------------------------------------------

/**
 * Returns 7 header elements using the pre-rotated weekDay array from the locale.
 * The locale's weekDay array is already rotated so index 0 = firstDay.
 */
export function createWeekdayHeaders(locale: LocaleConfig): HTMLElement[] {
  return locale.weekDay.map((label) => {
    const el = document.createElement('div');
    el.className = 'dp-weekday';
    el.setAttribute('role', 'columnheader');
    el.setAttribute('aria-label', label);
    el.textContent = label;
    return el;
  });
}

// ---------------------------------------------------------------------------
// Year / Month selects (quick navigation)
// ---------------------------------------------------------------------------

export function createYearSelect(
  viewYear: number,
  minYear?: number,
  maxYear?: number,
  localeCode?: string
): HTMLElement {
  const select = document.createElement('select');
  select.className = 'dp-year-select';
  select.setAttribute('aria-label', 'Select year');

  const start = minYear ?? viewYear - 20;
  const end = maxYear ?? viewYear + 20;

  for (let year = start; year <= end; year++) {
    const option = document.createElement('option');
    option.value = String(year);
    option.textContent = localizeDigits(String(year), localeCode ?? 'en-US');
    if (year === viewYear) option.selected = true;
    select.appendChild(option);
  }

  return select;
}

export function createMonthSelect(
  months: string[],
  viewMonth: number
): HTMLElement {
  const select = document.createElement('select');
  select.className = 'dp-month-select';
  select.setAttribute('aria-label', 'Select month');

  for (let i = 0; i < months.length; i++) {
    const option = document.createElement('option');
    option.value = String(i);
    option.textContent = months[i];
    if (i === viewMonth) option.selected = true;
    select.appendChild(option);
  }

  return select;
}

// ---------------------------------------------------------------------------
// Overlay
// ---------------------------------------------------------------------------

export function createOverlay(_trigger: HTMLElement): HTMLElement {
  const overlay = document.createElement('div');
  overlay.className = 'dp-overlay';
  overlay.setAttribute('aria-hidden', 'true');
  return overlay;
}

// ---------------------------------------------------------------------------
// Popup / dialog
// ---------------------------------------------------------------------------

export function createPopup(container: HTMLElement, zIndex: number): HTMLElement {
  const popup = document.createElement('div');
  popup.className = 'dp-popup';
  popup.setAttribute('role', 'dialog');
  popup.setAttribute('aria-modal', 'true');
  popup.setAttribute('aria-label', 'Date picker');
  popup.setAttribute('tabindex', '-1');
  popup.style.zIndex = String(zIndex);
  popup.style.display = 'none';
  container.appendChild(popup);
  return popup;
}

// ---------------------------------------------------------------------------
// Theme & direction
// ---------------------------------------------------------------------------

export function applyTheme(el: HTMLElement, theme: 'light' | 'dark'): void {
  el.classList.toggle('dp-theme-dark', theme === 'dark');
}

export function applyDirection(el: HTMLElement, direction: 'ltr' | 'rtl'): void {
  el.setAttribute('dir', direction);
}

// ---------------------------------------------------------------------------
// aria-live region
// ---------------------------------------------------------------------------

export function createAriaLiveRegion(): HTMLElement {
  const region = document.createElement('div');
  region.setAttribute('aria-live', 'polite');
  region.setAttribute('aria-atomic', 'true');
  region.className = 'dp-sr-only';
  return region;
}