import type { DatePickerOptions, DatePickerInstance } from './types';
import { EventEmitter } from './events';
import { StateManager } from './state';
import { getLocale, mergeLocale } from './i18n';
import {
  ISOFromDate,
  buildCalendarMonth,
  formatDate,
  parseDate,
  parseDateValue,
  dateEquals,
  isToday,
  calendarToGregorian,
  toCalendarComponents,
  type DateLimits,
} from './engine';
import {
  createCalendarCellElement,
  createWeekdayHeaders,
  createOverlay,
  createPopup,
  createAriaLiveRegion,
  applyTheme,
  applyDirection,
} from './dom';

// ---------------------------------------------------------------------------
// DatePicker — main class
// ---------------------------------------------------------------------------

export class DatePicker implements DatePickerInstance {
  private options: Partial<DatePickerOptions>;
  private state: StateManager;
  private events: EventEmitter;
  private container: HTMLElement | null = null;
  private inputEl: HTMLInputElement | null = null;
  private popup: HTMLElement | null = null;
  private overlay: HTMLElement | null = null;
  private liveRegion: HTMLElement | null = null;
  private destroyed = false;

  // Focused day cell index within the flat day grid
  private focusedDayIndex = -1;
  // Flat list of day button elements currently rendered
  private dayButtons: HTMLButtonElement[] = [];

  // Keyboard listener reference (for cleanup)
  private _keydownHandler: ((e: KeyboardEvent) => void) | null = null;
  private _outsideClickHandler: ((e: MouseEvent) => void) | null = null;

  constructor(el: HTMLElement | string, options: Partial<DatePickerOptions> = {}) {
    this.options = options;
    this.events = new EventEmitter();
    this.state = new StateManager();

    this.initContainer(el);
    this.initOptions();
    this.render();
    this.attachGlobalEvents();

    const s = this.state.getState();
    if (s.inline) {
      this._openInternal();
    } else {
      this.inputEl?.addEventListener('click', () => this.toggle());
      this.inputEl?.addEventListener('keydown', (e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          this.open();
        }
      });
    }
  }

  // ---------------------------------------------------------------------------
  // Init
  // ---------------------------------------------------------------------------

  private initContainer(el: HTMLElement | string): void {
    if (typeof el === 'string') {
      const element = document.querySelector(el);
      if (!element) throw new Error(`Element not found: ${el}`);
      this.container = element as HTMLElement;
    } else {
      this.container = el;
    }
  }

  private initOptions(): void {
    const opts = this.options;

    if (opts.mode) this.state.setMode(opts.mode);
    if (opts.calendar) this.state.setCalendar(opts.calendar);
    if (opts.showTime !== undefined) this.state.setShowTime(opts.showTime);
    if (opts.timeFormat) this.state.setTimeFormat(opts.timeFormat);
    if (opts.theme) this.state.setTheme(opts.theme);
    if (opts.inline !== undefined) this.state.setInline(opts.inline);
    if (opts.placeholder) this.state.setPlaceholder(opts.placeholder);
    if (opts.zIndex) this.state.setZIndex(opts.zIndex);
    if (opts.format) this.state.setFormat(opts.format);
    if (opts.firstDayOfWeek !== undefined) this.state.setFirstDayOfWeek(opts.firstDayOfWeek);

    // Locale
    const localeOpt = opts.locale ?? 'en-US';
    const localeCode = typeof localeOpt === 'string' ? localeOpt : localeOpt.code ?? 'en-US';
    this.state.setLocale(localeCode);

    // Auto-set calendar from locale if not explicitly set
    if (!opts.calendar) {
      const lc = getLocale(localeCode);
      this.state.setCalendar(lc.calendar);
    }

    // Auto-set firstDayOfWeek from locale if not explicitly set
    if (opts.firstDayOfWeek === undefined) {
      const lc = getLocale(localeCode);
      this.state.setFirstDayOfWeek(lc.firstDay);
    }

    // Value
    if (opts.value) {
      const s = this.state.getState();
      const calendar = s.calendar;
      const dates = Array.isArray(opts.value)
        ? opts.value.map((v) => parseDateValue(v, calendar)).filter((d): d is Date => d !== null)
        : (() => { const d = parseDateValue(opts.value as string, calendar); return d ? [d] : []; })();
      if (dates.length > 0) {
        this.state.setSelectedDates(dates);
        this.state.setViewDate(dates[0]);
      }
    }

    // minDate / maxDate
    if (opts.minDate) {
      const d = parseDateValue(opts.minDate);
      if (d) this.state.setMinDate(d);
    }
    if (opts.maxDate) {
      const d = parseDateValue(opts.maxDate);
      if (d) this.state.setMaxDate(d);
    }

    // disabledDates
    const disabledSet = new Set<string>();
    let disabledFn: ((d: Date) => boolean) | null = null;
    if (Array.isArray(opts.disabledDates)) {
      opts.disabledDates.forEach((d) => disabledSet.add(d));
    } else if (typeof opts.disabledDates === 'function') {
      disabledFn = opts.disabledDates;
    }
    this.state.setDisabledDates(disabledSet, disabledFn);
  }

  private getLocaleConfig() {
    const s = this.state.getState();
    const base = getLocale(s.locale);
    const localeOpt = this.options.locale;
    if (typeof localeOpt === 'object') {
      return mergeLocale(base, localeOpt);
    }
    return base;
  }

  // ---------------------------------------------------------------------------
  // Render
  // ---------------------------------------------------------------------------

  render(): void {
    if (!this.container || this.destroyed) return;
    this.container.innerHTML = '';

    const s = this.state.getState();
    const locale = this.getLocaleConfig();

    // Input element (popup mode only)
    if (!s.inline) {
      const wrapper = document.createElement('div');
      wrapper.className = 'dp-wrapper';
      wrapper.style.position = 'relative';

      const input = document.createElement('input');
      input.type = 'text';
      input.className = 'dp-input';
      input.placeholder = typeof this.options.placeholder === 'string'
        ? this.options.placeholder
        : locale.placeholder;
      input.readOnly = true;
      input.setAttribute('aria-haspopup', 'dialog');
      input.setAttribute('aria-expanded', 'false');
      input.setAttribute('autocomplete', 'off');

      // Set value
      input.value = this.formatValue(s);

      this.inputEl = input;
      wrapper.appendChild(input);

      // Overlay (backdrop)
      this.overlay = createOverlay(wrapper);
      document.body.appendChild(this.overlay);

      // Popup
      this.popup = createPopup(wrapper, s.zIndex);
      wrapper.appendChild(this.popup);

      this.container.appendChild(wrapper);
    } else {
      // Inline mode
      const wrapper = document.createElement('div');
      wrapper.className = 'dp-inline-wrapper';
      this.popup = createPopup(wrapper, s.zIndex);
      this.popup.style.display = 'block'; // always visible
      wrapper.appendChild(this.popup);
      this.container.appendChild(wrapper);
    }

    // aria-live region (screen reader announcements)
    this.liveRegion = createAriaLiveRegion();
    this.container.appendChild(this.liveRegion);

    applyTheme(this.popup!, s.theme);
    applyDirection(this.popup!, locale.direction);

    this.renderCalendar();
  }

  renderCalendar(): void {
    if (!this.popup) return;
    const s = this.state.getState();
    const locale = this.getLocaleConfig();

    // Convert Gregorian viewDate to target-calendar components
    const calComp = toCalendarComponents(s.viewDate, s.calendar) ?? {
      year: s.viewYear,
      month: s.viewMonth,
      day: 1,
    };

    const limits: DateLimits = {
      minDate: s.minDate,
      maxDate: s.maxDate,
      disabledDates: s.disabledDates,
      disabledDateFn: s.disabledDateFn,
    };

    // For range mode pass start/end separately
    let rangeStart: Date | null = null;
    let rangeEnd: Date | null = null;
    if (s.mode === 'range' && s.selectedDates.length >= 1) {
      rangeStart = s.selectedDates[0];
      rangeEnd = s.selectedDates[1] ?? null;
    }

    const month = buildCalendarMonth(
      calComp.year,
      calComp.month,
      s.firstDayOfWeek,
      s.calendar,
      limits,
      s.mode === 'range' ? [] : s.selectedDates,
      rangeStart,
      rangeEnd
    );

    this.popup.innerHTML = '';

    // ---- Header ----
    const header = document.createElement('div');
    header.className = 'dp-header';

    const prevBtn = document.createElement('button');
    prevBtn.type = 'button';
    prevBtn.className = 'dp-nav-btn dp-nav-btn--prev';
    prevBtn.innerHTML = locale.direction === 'rtl' ? '&#8250;' : '&#8249;';
    prevBtn.setAttribute('aria-label', 'Previous month');
    prevBtn.addEventListener('click', () => this.navigateMonth(-1));

    const monthYearLabel = document.createElement('div');
    monthYearLabel.className = 'dp-month-year';
    monthYearLabel.id = `dp-month-label-${Math.random().toString(36).slice(2)}`;
    monthYearLabel.textContent = `${locale.months[calComp.month]} ${calComp.year}`;
    monthYearLabel.setAttribute('aria-live', 'polite');

    const nextBtn = document.createElement('button');
    nextBtn.type = 'button';
    nextBtn.className = 'dp-nav-btn dp-nav-btn--next';
    nextBtn.innerHTML = locale.direction === 'rtl' ? '&#8249;' : '&#8250;';
    nextBtn.setAttribute('aria-label', 'Next month');
    nextBtn.addEventListener('click', () => this.navigateMonth(1));

    header.appendChild(prevBtn);
    header.appendChild(monthYearLabel);
    header.appendChild(nextBtn);
    this.popup.appendChild(header);

    // ---- Weekday headers ----
    const weekdayRow = document.createElement('div');
    weekdayRow.className = 'dp-weekdays';
    weekdayRow.setAttribute('role', 'row');
    createWeekdayHeaders(locale).forEach((h) => weekdayRow.appendChild(h));
    this.popup.appendChild(weekdayRow);

    // ---- Calendar grid ----
    const grid = document.createElement('div');
    grid.className = 'dp-grid';
    grid.setAttribute('role', 'grid');
    grid.setAttribute('aria-labelledby', monthYearLabel.id);

    this.dayButtons = [];
    let firstCurrentMonthIndex = -1;

    month.weeks.forEach((week) => {
      const rowEl = document.createElement('div');
      rowEl.setAttribute('role', 'row');
      rowEl.className = 'dp-week-row';

      week.days.forEach((cell) => {
        const btn = createCalendarCellElement(cell, locale) as HTMLButtonElement;
        btn.addEventListener('click', () => {
          if (!cell.isDisabled) this.selectDate(cell.date);
        });
        // Track focus index
        const idx = this.dayButtons.length;
        btn.addEventListener('focus', () => { this.focusedDayIndex = idx; });

        if (cell.isCurrentMonth && firstCurrentMonthIndex === -1) {
          firstCurrentMonthIndex = idx;
        }

        this.dayButtons.push(btn);
        rowEl.appendChild(btn);
      });

      grid.appendChild(rowEl);
    });

    // Set tabindex=0 on one focusable cell (today or first of month)
    if (this.dayButtons.length > 0) {
      let focusIdx = this.focusedDayIndex;
      if (focusIdx < 0 || focusIdx >= this.dayButtons.length) {
        // Try to find today in current month
        const todayIdx = this.dayButtons.findIndex(
          (_, i) => month.weeks.flatMap((w) => w.days)[i]?.isToday &&
            month.weeks.flatMap((w) => w.days)[i]?.isCurrentMonth
        );
        focusIdx = todayIdx >= 0 ? todayIdx : firstCurrentMonthIndex >= 0 ? firstCurrentMonthIndex : 0;
      }
      this.focusedDayIndex = focusIdx;
      this.dayButtons[focusIdx].tabIndex = 0;
    }

    this.popup.appendChild(grid);

    // ---- Footer ----
    const footer = document.createElement('div');
    footer.className = 'dp-footer';

    const todayBtn = document.createElement('button');
    todayBtn.type = 'button';
    todayBtn.className = 'dp-btn dp-btn--today';
    todayBtn.textContent = locale.today;
    todayBtn.addEventListener('click', () => this.goToToday());

    const clearBtn = document.createElement('button');
    clearBtn.type = 'button';
    clearBtn.className = 'dp-btn dp-btn--clear';
    clearBtn.textContent = locale.clear;
    clearBtn.addEventListener('click', () => this.clear());

    footer.appendChild(todayBtn);
    footer.appendChild(clearBtn);
    this.popup.appendChild(footer);
  }

  // ---------------------------------------------------------------------------
  // Date selection
  // ---------------------------------------------------------------------------

  private selectDate(date: Date): void {
    const s = this.state.getState();
    let selected = [...s.selectedDates];

    if (s.mode === 'single') {
      selected = [date];
    } else if (s.mode === 'multiple') {
      const idx = selected.findIndex((d) => dateEquals(d, date));
      if (idx >= 0) selected.splice(idx, 1);
      else selected.push(date);
    } else if (s.mode === 'range') {
      if (selected.length === 0 || selected.length >= 2) {
        selected = [date];
      } else {
        // Second click — ensure start <= end
        const start = selected[0];
        if (date < start) {
          selected = [date, start];
        } else {
          selected = [start, date];
        }
      }
    }

    this.state.setSelectedDates(selected);
    this.renderCalendar();
    this.updateInput();

    const shouldClose =
      s.mode === 'single' ||
      (s.mode === 'range' && selected.length === 2);

    this.events.emit('select', { date, value: this.getValue() });
    this.events.emit('change', { value: this.getValue() });

    if (shouldClose && !s.inline) {
      this.close();
    }
  }

  // ---------------------------------------------------------------------------
  // Navigation
  // ---------------------------------------------------------------------------

  navigateMonth(delta: number): void {
    const s = this.state.getState();
    // Work in calendar coordinates
    const calComp = toCalendarComponents(s.viewDate, s.calendar) ?? {
      year: s.viewYear,
      month: s.viewMonth,
      day: 1,
    };

    let month = calComp.month + delta;
    let year = calComp.year;

    if (month > 11) { month = 0; year++; }
    if (month < 0) { month = 11; year--; }

    // Convert back to Gregorian
    const newGregorian = calendarToGregorian(year, month, 1, s.calendar) ?? new Date(year, month, 1);
    this.state.setViewDate(newGregorian);
    this.focusedDayIndex = -1; // reset focus to first of month
    this.renderCalendar();

    const locale = this.getLocaleConfig();
    const calComp2 = toCalendarComponents(newGregorian, s.calendar) ?? { year, month, day: 1 };
    const announcement = `${locale.months[calComp2.month]} ${calComp2.year}`;
    this.announce(announcement);

    this.events.emit('navigate', { year: calComp2.year, month: calComp2.month });
  }

  goToToday(): void {
    const today = new Date();
    this.state.setViewDate(today);
    this.focusedDayIndex = -1;
    this.renderCalendar();
  }

  // ---------------------------------------------------------------------------
  // Keyboard navigation
  // ---------------------------------------------------------------------------

  private attachGlobalEvents(): void {
    this._keydownHandler = (e: KeyboardEvent) => this.handleKeydown(e);
    this._outsideClickHandler = (e: MouseEvent) => {
      if (this.destroyed || !this.state.getState().isOpen) return;
      const target = e.target as Node;
      if (this.popup && !this.popup.contains(target) &&
        this.inputEl && !this.inputEl.contains(target)) {
        this.close();
      }
    };

    document.addEventListener('keydown', this._keydownHandler);
    document.addEventListener('mousedown', this._outsideClickHandler);
  }

  private handleKeydown(e: KeyboardEvent): void {
    if (this.destroyed || !this.state.getState().isOpen) return;

    const isInPopup = this.popup?.contains(document.activeElement);
    const isOnInput = document.activeElement === this.inputEl;

    // Escape closes
    if (e.key === 'Escape') {
      e.preventDefault();
      this.close();
      this.inputEl?.focus();
      return;
    }

    // Only handle arrow keys when focus is inside popup or on input
    if (!isInPopup && !isOnInput) return;

    const total = this.dayButtons.length;
    if (total === 0) return;

    let idx = this.focusedDayIndex;
    if (idx < 0) idx = 0;

    switch (e.key) {
      case 'ArrowRight':
        e.preventDefault();
        idx = (idx + 1) % total;
        break;
      case 'ArrowLeft':
        e.preventDefault();
        idx = (idx - 1 + total) % total;
        break;
      case 'ArrowDown':
        e.preventDefault();
        if (idx + 7 < total) idx += 7;
        else this.navigateMonth(1);
        return;
      case 'ArrowUp':
        e.preventDefault();
        if (idx - 7 >= 0) idx -= 7;
        else this.navigateMonth(-1);
        return;
      case 'Home':
        e.preventDefault();
        // Go to first day of current week row (find start of current row)
        idx = Math.floor(idx / 7) * 7;
        break;
      case 'End':
        e.preventDefault();
        idx = Math.floor(idx / 7) * 7 + 6;
        if (idx >= total) idx = total - 1;
        break;
      case 'PageUp':
        e.preventDefault();
        this.navigateMonth(-1);
        return;
      case 'PageDown':
        e.preventDefault();
        this.navigateMonth(1);
        return;
      case 'Enter':
      case ' ':
        e.preventDefault();
        this.dayButtons[idx]?.click();
        return;
      case 'Tab':
        // Allow Tab to cycle through focusable elements naturally
        return;
      default:
        return;
    }

    this.focusedDayIndex = idx;
    this.updateFocusedCell(idx);
  }

  private updateFocusedCell(idx: number): void {
    // Reset all tabIndexes
    this.dayButtons.forEach((b, i) => {
      b.tabIndex = i === idx ? 0 : -1;
    });
    this.dayButtons[idx]?.focus();
  }

  // ---------------------------------------------------------------------------
  // Focus trap
  // ---------------------------------------------------------------------------

  private trapFocus(): void {
    if (!this.popup) return;
    const focusableSelectors = 'button:not([disabled]), [tabindex="0"]';
    const focusable = Array.from(
      this.popup.querySelectorAll<HTMLElement>(focusableSelectors)
    );
    if (focusable.length > 0) {
      focusable[0].focus();
    }
  }

  // ---------------------------------------------------------------------------
  // Open / Close
  // ---------------------------------------------------------------------------

  private _openInternal(): void {
    this.state.setIsOpen(true);
    if (this.popup) this.popup.style.display = 'block';
    if (this.overlay) {
      this.overlay.style.display = 'block';
      this.overlay.addEventListener('click', () => this.close(), { once: true });
    }
    this.inputEl?.setAttribute('aria-expanded', 'true');
    this.events.emit('open', {});
  }

  open(): void {
    if (this.destroyed || this.state.getState().isOpen) return;
    this._openInternal();
    // Focus the popup after a microtask so display:block takes effect
    requestAnimationFrame(() => {
      if (this.focusedDayIndex >= 0) {
        this.updateFocusedCell(this.focusedDayIndex);
      } else {
        this.trapFocus();
      }
    });
  }

  close(): void {
    if (this.destroyed || !this.state.getState().isOpen) return;
    this.state.setIsOpen(false);
    if (this.popup) this.popup.style.display = 'none';
    if (this.overlay) this.overlay.style.display = 'none';
    this.inputEl?.setAttribute('aria-expanded', 'false');
    this.events.emit('close', {});
  }

  toggle(): void {
    if (this.state.getState().isOpen) this.close();
    else this.open();
  }

  // ---------------------------------------------------------------------------
  // Public API
  // ---------------------------------------------------------------------------

  destroy(): void {
    if (this.destroyed) return;
    this.destroyed = true;
    this.close();
    this.events.destroy();

    if (this._keydownHandler) {
      document.removeEventListener('keydown', this._keydownHandler);
    }
    if (this._outsideClickHandler) {
      document.removeEventListener('mousedown', this._outsideClickHandler);
    }
    // Remove overlay from body if appended there
    if (this.overlay?.parentNode === document.body) {
      document.body.removeChild(this.overlay);
    }
    if (this.container) this.container.innerHTML = '';
  }

  getValue(): string | string[] | null {
    const s = this.state.getState();
    if (s.selectedDates.length === 0) return null;
    if (s.mode === 'single') return formatDate(s.selectedDates[0], s.format);
    return s.selectedDates.map((d) => formatDate(d, s.format));
  }

  setValue(v: string | string[]): void {
    const s = this.state.getState();
    const dates = Array.isArray(v)
      ? v.map((x) => parseDateValue(x, s.calendar)).filter((d): d is Date => d !== null)
      : (() => { const d = parseDateValue(v, s.calendar); return d ? [d] : []; })();

    if (dates.length > 0) {
      this.state.setSelectedDates(dates);
      this.state.setViewDate(dates[0]);
      this.renderCalendar();
      this.updateInput();
      this.events.emit('change', { value: this.getValue() });
    }
  }

  clear(): void {
    this.state.setSelectedDates([]);
    this.renderCalendar();
    this.updateInput();
    this.events.emit('clear', {});
  }

  setLocale(l: string): void {
    this.state.setLocale(l);
    const lc = getLocale(l);
    this.state.setCalendar(lc.calendar);
    this.state.setFirstDayOfWeek(lc.firstDay);
    if (this.popup) {
      applyDirection(this.popup, lc.direction);
    }
    this.renderCalendar();
    this.updateInput();
  }

  on(event: string, cb: (payload: any) => void): () => void {
    return this.events.on(event, cb);
  }

  update(options: Partial<DatePickerOptions>): void {
    this.options = { ...this.options, ...options };
    this.initOptions();
    this.render();
  }

  // ---------------------------------------------------------------------------
  // Private helpers
  // ---------------------------------------------------------------------------

  private updateInput(): void {
    if (!this.inputEl) return;
    const s = this.state.getState();
    this.inputEl.value = this.formatValue(s);
  }

  private formatValue(s: ReturnType<StateManager['getState']>): string {
    if (s.selectedDates.length === 0) return '';
    return s.selectedDates.map((d) => formatDate(d, s.format)).join(' – ');
  }

  private announce(message: string): void {
    if (!this.liveRegion) return;
    this.liveRegion.textContent = '';
    // Force repaint so screen readers pick up the change
    requestAnimationFrame(() => {
      if (this.liveRegion) this.liveRegion.textContent = message;
    });
  }
}